arguments.content:
:root {
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #172033;
  background: #f6f8fb;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background:
    radial-gradient(circle at top left, rgba(79, 70, 229, 0.10), transparent 34rem),
    linear-gradient(135deg, #fbfcff 0%, #eef3f9 100%);
}

button {
  font: inherit;
}

.app-shell {
  width: min(1180px, calc(100% - 40px));
  margin: 0 auto;
  padding: 44px 0 56px;
}

.hero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 28px;
}

.eyebrow {
  margin: 0 0 8px;
  color: #4f46e5;
  font-size: 0.9rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  color: #101828;
  font-size: clamp(2.5rem, 7vw, 5rem);
  line-height: 0.95;
  letter-spacing: -0.07em;
}

.subtitle {
  margin: 14px 0 0;
  color: #667085;
  font-size: 1.05rem;
}

.add-button {
  border: 0;
  border-radius: 999px;
  background: #111827;
  color: white;
  box-shadow: 0 16px 34px rgba(17, 24, 39, 0.18);
  cursor: default;
  font-weight: 800;
  padding: 14px 22px;
  white-space: nowrap;
}

.board {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 20px;
}

.column {
  min-height: 520px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  border-radius: 28px;
  background: rgba(255, 255, 255, 0.82);
  box-shadow: 0 20px 55px rgba(15, 23, 42, 0.08);
  padding: 18px;
}

.column-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
  padding: 4px 2px;
}

.column-title-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
}

.column-dot {
  width: 11px;
  height: 11px;
  border-radius: 999px;
  box-shadow: 0 0 0 5px rgba(99, 102, 241, 0.09);
}

h2 {
  margin: 0;
  color: #1f2937;
  font-size: 1.02rem;
  letter-spacing: -0.02em;
}

.count {
  display: grid;
  place-items: center;
  min-width: 30px;
  height: 30px;
  border-radius: 999px;
  background: #f1f5f9;
  color: #64748b;
  font-size: 0.85rem;
  font-weight: 800;
}

.cards {
  display: grid;
  gap: 14px;
}

.card {
  border: 1px solid #e8edf4;
  border-radius: 22px;
  background: #ffffff;
  box-shadow: 0 12px 26px rgba(15, 23, 42, 0.06);
  padding: 18px;
  transition: transform 180ms ease, box-shadow 180ms ease;
}

.card:hover {
  transform: translateY(-2px);
  box-shadow: 0 18px 32px rgba(15, 23, 42, 0.10);
}

.card-topline {
  display: flex;
  justify-content: flex-end;
  margin-bottom: 16px;
}

.priority {
  border-radius: 999px;
  font-size: 0.74rem;
  font-weight: 800;
  padding: 6px 10px;
}

.priority.high {
  background: #fee2e2;
  color: #b42318;
}

.priority.medium {
  background: #fef3c7;
  color: #a15c07;
}

.priority.low {
  background: #dcfce7;
  color: #167647;
}

h3 {
  margin: 0;
  color: #101828;
  font-size: 1.15rem;
  line-height: 1.25;
  letter-spacing: -0.025em;
}

.card p {
  margin: 12px 0 0;
  color: #667085;
  font-size: 0.95rem;
  font-weight: 650;
}

@media (max-width: 820px) {
  .hero {
    align-items: flex-start;
    flex-direction: column;
  }

  .board {
    grid-template-columns: 1fr;
  }

  .column {
    min-height: auto;
  }
}

